class WorkspaceResolutionMiddleware(BaseHTTPMiddleware):
    async def dispatch(self, request: Request, call_next):
        ws_id = request.headers.get("X-Workspace-Context")
        request.state.workspace_id = ws_id
        return await call_next(request)

app.add_middleware(WorkspaceResolutionMiddleware)

@app.post("/api/v1/webhooks/deliveries/{delivery_id}/retry")
async def retry_webhook_delivery(
    delivery_id: str,
    request: Request,
    dispatcher: WebhookDispatcher = Depends(get_webhook_dispatcher),
    current_user: User = Depends(get_current_user)
):
    workspace_id = request.state.workspace_id
    if not workspace_id or workspace_id not in current_user.enrolled_workspace_ids:
        raise HTTPException(status_code=403, detail="Unauthorized workspace context")
    delivery = await dispatcher.find_delivery(delivery_id=delivery_id, workspace_id=workspace_id)
    if not delivery:
        raise HTTPException(status_code=404, detail="Webhook delivery not found")
    await dispatcher.schedule_retry(delivery)
    return {"status": "retry_scheduled", "delivery_id": delivery_id}
